// Traduce el evento de Chatwoot al formato que espera el endpoint del funnel.
// Se hace en un Code node y no en expresiones sueltas para que quede en un
// solo lugar legible: si Chatwoot cambia el shape del payload, se toca aqui.
//
// BUG REAL encontrado y corregido el 14/09/2026: el nodo Webhook de n8n
// SIEMPRE envuelve el POST real dentro de item.json.body -- item.json trae
// { headers, params, query, body, webhookUrl, executionMode }, nunca la
// conversacion directamente. La version anterior de este Code (desde el
// 26/08/2026, sin cambios en esto hasta hoy) leia directo de item.json y
// nunca leyo nada real: siempre mandaba todo vacio. Se detecto con un
// payload real pineado en el nodo Webhook (conversacion 1858, inbox 83,
// estado "interesado") que devolvia _enviar:false con todos los campos en
// blanco. Verificado el fix contra ESE MISMO payload real, no uno simulado.
//
// ACTUALIZADO 14/09/2026: Trade Cars paso de dos custom attributes separados
// (perfil_coincide + status) a uno solo (estado), con una automatizacion de
// Chatwoot que ademas le pone una etiqueta de color a la conversacion segun
// ese valor. La etiqueta es SOLO cosmetica para las personas -- este nodo NO
// la lee ni la necesita, lee directo el custom attribute "estado".
//
// El endpoint del dashboard NO cambio: sigue esperando perfil_coincide+status
// por separado (son los que alimentan las columnas GENERATED etapa/etapa_rank
// y el trigger anti-regresion en sql/tradecars_funnel.sql). Por eso la
// traduccion vive aqui, no en el backend: mueve el problema a un solo lugar
// legible en vez de tocar una tabla con miles de filas ya migradas.

const salida = [];

// "estado" (Chatwoot) -> (perfil_coincide, status) que ya entiende el dashboard.
// Verificado contra utils/tradecarsFunnel.ts: cada fila cae en su barra exacta
// del embudo (LEADS...COMPRAS), en orden.
//
// "lead" manda perfil_coincide vacio, NO "NO": "NO" en el dashboard significa
// "no cumple la politica de compra" (rechazo definitivo, se queda pegado en
// LEADS para siempre). "lead" es solo "todavia sin calificar" -- vacio logra
// lo mismo (cae en LEADS) sin marcarlo como rechazado.
const ESTADO_A_CAMPOS = {
  lead:            { perfil_coincide: '',   status: '' },
  cumple_politica: { perfil_coincide: 'SI', status: 'NO CONTACTADO'   },
  contactado:      { perfil_coincide: 'SI', status: 'NO INTERESADO'  },
  interesado:      { perfil_coincide: 'SI', status: 'EN SEGUIMIENTO' },
  cita_agendada:   { perfil_coincide: 'SI', status: 'CITA'           },
  cita_asistida:   { perfil_coincide: 'SI', status: 'CITA ASISTIDA'  },
  compra:          { perfil_coincide: 'SI', status: 'CONCRETADA'     },
  // "clientes" queda AFUERA a proposito -- confirmado con el cliente el
  // 14/09/2026: por ahora eso se revisa a mano, no representa una etapa del
  // embudo. Si mas adelante cambia, agregarla aca.
};

// Canal e inboxes de Trade Cars -- confirmados por el cliente el 14/09/2026.
// Si se agrega un inbox nuevo del mismo canal (ej. un segundo numero de
// WhatsApp), agregar su id tambien en INBOX_A_CANAL e INBOX_A_CAMPANA.
const INBOX_A_CANAL = {
  88: 'WhatsApp',
  81: 'Instagram',
  82: 'TikTok',
  83: 'Facebook',   // Messenger entra bajo el mismo canal que Facebook Page
};

// Respaldo por tipo de canal, para cualquier inbox que no este en la lista
// de arriba.
const CANALES_POR_TIPO = {
  'Channel::Whatsapp':     'WhatsApp',
  'Channel::Instagram':    'Instagram',
  'Channel::FacebookPage': 'Facebook',
  'Channel::Tiktok':       'TikTok',
  'Channel::Api':          'API',
  'Channel::WebWidget':    'Web',
  'Channel::Email':        'Email',
};

// La campana ES el canal de origen -- decision del cliente del 14/09/2026:
// no hay un custom attribute "campana" en Chatwoot, ni hace falta crearlo.
// OJO: el nombre no siempre coincide con el de INBOX_A_CANAL (el inbox 83 es
// "Facebook" para el filtro de canal de todo el dashboard, pero "Messenger"
// como campana, que es como el cliente lo quiere ver en este reporte).
//
// "WEB" queda reservado para mas adelante -- hoy no hay inbox de Chatwoot
// para la web: esos leads entran por server/api/tradecars/formulario.ts,
// a otra tabla (tradecars_solicitudes_venta/compra), y ese endpoint todavia
// no escribe nada en tradecars_funnel_leads.campana. Cuando se conecte,
// usar el mismo valor exacto "WEB" para que quede junto a estas 4.
const INBOX_A_CAMPANA = {
  88: 'WhatsApp',
  81: 'Instagram',
  82: 'TikTok',
  83: 'Messenger',
};

for (const item of $input.all()) {
  const raw = item.json || {};

  // El Webhook de n8n SIEMPRE entrega { headers, params, query, body, ... } --
  // el POST real de Chatwoot esta en .body, nunca al nivel raiz. Si alguien
  // prueba pegando solo el cuerpo de Chatwoot (sin el sobre de n8n), raw.body
  // no existe y se usa raw directo -- por eso el fallback.
  const c = raw.body ?? raw;

  // Segun la version, Chatwoot manda la conversacion directo en .body o
  // anidada un nivel mas adentro en .body.conversation.
  const conv  = c.conversation || c;
  const attrs = conv.custom_attributes || c.custom_attributes || {};
  const meta  = conv.meta || c.meta || {};

  // Chatwoot manda las fechas como epoch en segundos o como ISO, segun el campo
  const aFecha = (v) => {
    if (v === null || v === undefined || v === '') return null;
    if (typeof v === 'number') return new Date(v * 1000).toISOString().slice(0, 10);
    const s = String(v).trim();
    if (/^\d{10}$/.test(s)) return new Date(Number(s) * 1000).toISOString().slice(0, 10);
    const d = new Date(s);
    return isNaN(d.getTime()) ? s : d.toISOString().slice(0, 10);
  };

  // Canal: primero por inbox_id (no es ambiguo), si no esta en la lista cae
  // al tipo de canal como respaldo.
  const inboxId = conv.inbox_id ?? c.inbox_id ?? null;
  const canal = INBOX_A_CANAL[inboxId] || CANALES_POR_TIPO[conv.channel] || conv.channel || '';
  const campana = INBOX_A_CAMPANA[inboxId] || '';

  // Traduccion del estado nuevo. Si Chatwoot manda algo que no esta en la
  // lista (typo, opcion nueva sin avisar, o "clientes"), NO se envia nada:
  // es preferible dejarlo sin sincronizar a borrar por error una
  // clasificacion que el lead ya tenia.
  const estadoRaw = String(attrs.estado || '').trim().toLowerCase();
  const mapeo = ESTADO_A_CAMPOS[estadoRaw];

  let perfilCoincide = '';
  let status = '';
  let enviar = false;

  if (mapeo) {
    perfilCoincide = mapeo.perfil_coincide;
    status = mapeo.status;
    enviar = true;
  } else if (!estadoRaw && (attrs.perfil_coincide || attrs.status)) {
    // Compatibilidad con el formato viejo (dos campos separados), por si
    // alguna conversacion todavia los tiene cargados de antes del cambio.
    perfilCoincide = attrs.perfil_coincide || '';
    status = attrs.status || '';
    enviar = true;
  } else if (estadoRaw) {
    console.log(`[tradecars-funnel] estado no reconocido, se ignora: "${estadoRaw}" (conv ${conv.id})`);
  }

  const payload = {
    // Automatico del CRM
    conversation_id: conv.id ?? null,
    account_id:      conv.account_id ?? c.account?.id ?? conv.messages?.[0]?.account_id ?? null,
    contact_id:      meta.sender?.id ?? null,
    nombre:          meta.sender?.name || '',
    telefono:        meta.sender?.phone_number || '',
    canal,
    campana,
    asesor:          meta.assignee?.name || '',
    fecha_derivacion: aFecha(conv.created_at),

    // Traducidos desde "estado" (o formato viejo, ver arriba)
    perfil_coincide: perfilCoincide,
    status:          status,

    // El resto de los custom attributes, igual que antes
    fecha_cita:           aFecha(attrs.fecha_cita),
    fecha_compra:         aFecha(attrs.fecha_compra),
    motivo_no_cita:       attrs.motivo_no_cita || '',
    fecha_probable_venta: aFecha(attrs.fecha_probable_venta),
    proxima_accion:       attrs.proxima_accion || '',
    fecha_seguimiento:    aFecha(attrs.fecha_seguimiento),
  };

  // Chatwoot dispara conversation_updated en CADA mensaje. Solo tiene sentido
  // escribir cuando ya se pudo traducir un estado valido.
  payload._enviar = enviar;

  salida.push({ json: payload });
}

return salida;
